<template>
  <div class="page-stack director-page">
    <header class="page-heading with-action">
      <div><RouterLink class="back-link" :to="`/projects/${projectUuid}/studio`"><ArrowLeft :size="16" />返回创作台</RouterLink><p class="overline">DIRECTOR EVIDENCE</p><h1>实验导演工作台</h1><p>只展示持久化的计划、工具、候选、实验与审批证据。</p></div>
      <button v-if="view" class="button ghost" type="button" :disabled="loading" @click="load"><RefreshCw :size="16" :class="{spin:loading}" />刷新证据</button>
    </header>
    <form v-if="!view" class="director-card goal-form" @submit.prevent="createRun">
      <h2>创建受限 DesignGoal</h2><label><span>目标说明（不会作为完整 Prompt 展示）</span><textarea v-model="form.goal" required minlength="10" maxlength="1000" rows="4" /></label>
      <div class="director-grid"><label><span>指标</span><select v-model="form.metric"><option value="NOVICE_COMPLETION_RATE">新手完成率</option><option value="REGULAR_COMPLETION_RATE">普通玩家完成率</option><option value="P95_COMPLETION_TIME">P95 完成时间</option><option value="DEATH_RATE">死亡率</option></select></label><label><span>最小目标</span><input v-model.number="form.minimum" type="number" min="0" max="1" step="0.05" /></label><label><span>最大轮次</span><input v-model.number="form.maxRounds" type="number" min="1" max="20" /></label><label><span>最大 Episodes</span><input v-model.number="form.maxEpisodes" type="number" min="1" max="100" /></label></div>
      <p class="evidence-note">固定保护预算：每轮最多 4 次工具调用、3 个候选；总成本和执行时间均有硬上限。</p><p v-if="error" class="alert danger" role="alert">{{ error }}</p><button class="button primary" :disabled="loading">{{ loading ? "正在创建…" : "启动 Director Run" }}</button>
    </form>
    <template v-else>
      <p v-if="error" class="alert danger" role="alert">{{ error }}</p>
      <section class="director-card run-summary"><div><small>状态</small><strong>{{ view.run.status }}</strong><span>{{ waitReason(view.run) }}</span></div><div><small>Run</small><code>{{ view.run.runUuid }}</code><span>attempt {{ view.run.executionAttempt || 0 }} · state v{{ view.run.stateVersion }}</span></div><div><small>目标摘要</small><code>{{ view.run.goalDigest }}</code><span>创建于 {{ formatTime(view.run.createdAt) }}</span></div></section>
      <section class="director-card"><header class="section-head"><div><h2>预算事实</h2><p>used / maximum · remaining</p></div><button v-if="!terminal" class="button ghost" type="button" :disabled="acting" @click="cancelRun">取消运行</button></header><div class="budget-grid"><article v-for="row in budgets" :key="row.label"><small>{{ row.label }}</small><strong>{{ row.used }} / {{ row.maximum }}</strong><span>剩余 {{ row.remaining }}</span></article></div></section>
      <section v-if="canApprove" class="director-card approval-card"><h2>需要真实用户审批</h2><p>审批只调用受保护的 PrototypeVersion approval API；重复点击复用同一 Idempotency-Key。</p><label><span>审批理由</span><textarea v-model="approvalReason" maxlength="500" rows="3" /></label><div class="approval-actions"><button class="button primary" :disabled="acting || !approvalReason.trim()" @click="decide('APPROVED')">批准 DRAFT</button><button class="button ghost" :disabled="acting || !approvalReason.trim()" @click="decide('REJECTED')">拒绝 DRAFT</button></div><p v-if="approvalResult" class="alert">{{ approvalResult.decision }} · {{ approvalResult.reused ? "幂等复用" : "已记录" }}</p></section>
      <div class="evidence-columns">
        <section class="director-card"><h2>决策时间线</h2><p v-if="!view.decisions?.length" class="evidence-note">尚无持久化决策。</p><ol v-else class="timeline"><li v-for="decision in pageOf(view.decisions, decisionPage)" :key="decision.decisionUuid"><span>{{ decision.roundNumber }}</span><div><strong>{{ decision.kind }}</strong><p>{{ decision.reasonSummary || "无摘要" }}</p><code>{{ decision.decisionDigest }}</code><small>{{ formatTime(decision.createdAt) }}</small></div></li></ol><EvidencePager :page="decisionPage" :total="view.decisions.length" @change="decisionPage=$event" /></section>
        <section class="director-card"><h2>工具证据</h2><p v-if="!view.toolCalls?.length" class="evidence-note">尚无工具调用。</p><template v-else><article v-for="call in pageOf(view.toolCalls, toolPage)" :key="call.callUuid" class="tool-evidence"><header><strong>{{ call.toolName }} <small>{{ call.toolVersion }}</small></strong><span :class="['tool-status', call.status==='FAILED'?'failed':'']">{{ call.status }}</span></header><dl><div><dt>输入 digest</dt><dd><code>{{ call.inputDigest }}</code></dd></div><div><dt>输出 digest</dt><dd><code>{{ call.outputDigest || '—' }}</code></dd></div><div><dt>耗时 / 重试</dt><dd>{{ call.durationMs ?? '—' }} ms / {{ call.retryCount || 0 }}</dd></div><div v-if="call.errorCode"><dt>错误</dt><dd>{{ call.errorCode }}</dd></div></dl><p>{{ call.outputSummary || call.inputSummary || "无脱敏摘要" }}</p></article></template><EvidencePager :page="toolPage" :total="view.toolCalls.length" @change="toolPage=$event" /></section>
      </div>
      <section class="director-card"><h2>基线 / 候选与 Persona 指标</h2><p v-if="!view.candidates?.length" class="evidence-note">尚无持久化候选。</p><div v-else class="candidate-grid"><article v-for="candidate in view.candidates" :key="candidate.candidateUuid"><header><strong>候选 {{ candidate.ordinalNumber }}</strong><span>{{ candidate.status }}</span></header><dl><div><dt>生成器</dt><dd>{{ candidate.generatorVersion }}</dd></div><div><dt>Config digest</dt><dd><code>{{ candidate.configDigest || '—' }}</code></dd></div></dl><details><summary>受限参数与服务端指标</summary><pre>{{ pretty(candidateEvidence(candidate)) }}</pre></details><div class="candidate-links"><RouterLink v-if="candidate.prototypeVersionUuid" :to="`/projects/${projectUuid}/versions/${candidate.prototypeVersionUuid}/episodes`">PlayerRun / Episode Trace</RouterLink><span v-else>尚未关联 Episode</span></div></article></div></section>
    </template>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ArrowLeft, RefreshCw } from "@lucide/vue";
import { directorApi } from "../../shared/api/director";
import { createIdempotencyKey } from "../../shared/presentation/submission";
import { approvalVersion, budgetRows, candidateEvidence, waitReason } from "./directorEvidence";
const PAGE_SIZE=10;
const EvidencePager=defineComponent({props:{page:Number,total:Number},emits:["change"],setup(props,{emit}){return()=>props.total>PAGE_SIZE?h("nav",{class:"evidence-pager","aria-label":"证据分页"},[h("button",{disabled:props.page===0,onClick:()=>emit("change",props.page-1)},"上一页"),h("span",`${props.page+1} / ${Math.ceil(props.total/PAGE_SIZE)}`),h("button",{disabled:(props.page+1)*PAGE_SIZE>=props.total,onClick:()=>emit("change",props.page+1)},"下一页")]):null;}});
const route=useRoute(),router=useRouter(),projectUuid=computed(()=>String(route.params.projectUuid)),runUuid=computed(()=>String(route.params.runUuid||""));
const view=ref(null),loading=ref(false),acting=ref(false),error=ref(""),approvalReason=ref(""),approvalResult=ref(null),decisionPage=ref(0),toolPage=ref(0);
const form=reactive({goal:"提高新手完成率，同时保持专家玩家的挑战性。",metric:"NOVICE_COMPLETION_RATE",minimum:.7,maxRounds:4,maxEpisodes:12});let createKey=createIdempotencyKey();const approvalKeys=new Map();
const budgets=computed(()=>budgetRows(view.value?.run)),terminal=computed(()=>["SUCCEEDED","FAILED","CANCELED"].includes(view.value?.run?.status)),canApprove=computed(()=>view.value?.run?.status==="WAITING_APPROVAL"&&approvalVersion(view.value.run.waitingApprovalRef));
onMounted(()=>{if(runUuid.value)load();});
async function sha(value){const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value));return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,"0")).join("");}
async function createRun(){loading.value=true;error.value="";try{const body={goal:{protocolVersion:"director/1.0",sourceTextDigest:await sha(form.goal.trim()),metrics:[{name:form.metric,target:{min:Number(form.minimum)}}],guardrails:[{name:"NO_REGRESSION",summary:"保留专家挑战性"}]},budget:{maxRounds:Number(form.maxRounds),maxToolCalls:Number(form.maxRounds)*4,maxCandidates:3,maxEpisodes:Number(form.maxEpisodes),maxTokens:20000,maxCostMicros:2000000,maxWallClockMs:900000,maxFailures:3},facts:{source:"director-evidence-ui",summary:form.goal.trim().slice(0,160)}};const created=await directorApi.create(projectUuid.value,body,createKey);createKey=createIdempotencyKey();await router.replace(`/projects/${projectUuid.value}/director-runs/${created.runUuid}`);await load(created.runUuid);}catch(cause){error.value=cause.message||"无法创建 Director Run";}finally{loading.value=false;}}
async function load(explicit=runUuid.value){loading.value=true;error.value="";try{view.value=await directorApi.get(projectUuid.value,explicit);decisionPage.value=Math.min(decisionPage.value,Math.max(0,Math.ceil((view.value.decisions?.length||0)/PAGE_SIZE)-1));toolPage.value=Math.min(toolPage.value,Math.max(0,Math.ceil((view.value.toolCalls?.length||0)/PAGE_SIZE)-1));}catch(cause){error.value=cause.message||"无法读取 Director 证据";}finally{loading.value=false;}}
async function cancelRun(){acting.value=true;error.value="";try{await directorApi.cancel(projectUuid.value,view.value.run.runUuid,view.value.run.stateVersion);await load();}catch(cause){error.value=cause.message||"取消失败";}finally{acting.value=false;}}
async function decide(decision){if(acting.value)return;acting.value=true;error.value="";const version=approvalVersion(view.value.run.waitingApprovalRef),key=`${version}:${decision}`;if(!approvalKeys.has(key))approvalKeys.set(key,createIdempotencyKey());try{approvalResult.value=await directorApi.approve(projectUuid.value,version,decision,approvalReason.value.trim(),approvalKeys.get(key));await load();}catch(cause){error.value=cause.message||"审批失败";}finally{acting.value=false;}}
function pageOf(items,page){return (items||[]).slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE);}function pretty(value){return JSON.stringify(value,null,2);}function formatTime(value){return value?new Intl.DateTimeFormat("zh-CN",{dateStyle:"short",timeStyle:"medium"}).format(new Date(value)):"—";}
</script>

<style scoped>
.director-page{max-width:1280px;margin:auto}.director-card{background:#fff;border:1px solid var(--line);border-radius:8px;padding:22px;min-width:0}.director-card h2{font-size:18px;margin:0 0 16px}.goal-form{display:grid;gap:18px}.goal-form label,.approval-card label{display:grid;gap:7px}.director-grid,.budget-grid,.candidate-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.director-grid label{display:grid;gap:7px}.director-grid input,.director-grid select{min-height:42px;border:1px solid var(--line);border-radius:6px;padding:0 10px}.evidence-note{color:var(--muted);font-size:13px}.run-summary{display:grid;grid-template-columns:1fr 1.4fr 1.4fr;gap:16px}.run-summary>div,.budget-grid article{display:grid;gap:6px}.run-summary code,.tool-evidence code,.candidate-grid code{font-size:11px;overflow-wrap:anywhere}.run-summary span,.budget-grid span{color:var(--muted);font-size:12px}.section-head,.approval-actions,.tool-evidence header,.candidate-grid header{display:flex;justify-content:space-between;align-items:center;gap:12px}.section-head p{margin:3px 0;color:var(--muted);font-size:12px}.budget-grid article{background:#f7f8fa;padding:12px;border-radius:6px}.evidence-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.timeline{list-style:none;padding:0;margin:0;display:grid;gap:12px}.timeline li{display:grid;grid-template-columns:32px 1fr;gap:10px}.timeline li>span{display:flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:50%;background:#eaf0ff;color:var(--primary);font-weight:800}.timeline li div{display:grid;gap:4px}.timeline p,.tool-evidence p{margin:0;color:var(--muted);font-size:12px}.timeline small{color:var(--muted)}.tool-evidence{border-top:1px solid var(--line);padding:14px 0;display:grid;gap:10px}.tool-evidence dl,.candidate-grid dl{display:grid;gap:7px;margin:0}.tool-evidence dl div,.candidate-grid dl div{display:grid;grid-template-columns:110px 1fr;gap:8px;font-size:12px}.tool-evidence dd,.candidate-grid dd{margin:0}.tool-status{color:var(--success);font-size:11px}.tool-status.failed{color:var(--danger)}.evidence-pager{display:flex;justify-content:center;align-items:center;gap:12px;margin-top:14px}.candidate-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.candidate-grid article{border:1px solid var(--line);border-radius:7px;padding:14px;display:grid;gap:12px}.candidate-grid pre{max-height:220px;overflow:auto;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}.candidate-links{font-size:12px}.approval-card{border-left:4px solid var(--warning)}.approval-actions{justify-content:flex-start;margin-top:12px}@media(max-width:900px){.director-grid,.budget-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.evidence-columns,.run-summary{grid-template-columns:1fr}.candidate-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.director-grid,.budget-grid,.candidate-grid{grid-template-columns:1fr}.approval-actions{align-items:stretch;flex-direction:column}.approval-actions button{width:100%}}
.director-page,.timeline li div{min-width:0}.director-card{overflow:hidden}.timeline code{overflow-wrap:anywhere;word-break:break-all}
</style>
